export const EMBEDDED_VIEWS: Record<string, string> = {
  "builder": "<%- include('partials/header') %>\n\n<% if (msg) { %>\n<div class=\"banner\" style=\"background:#e8f5e9;border-color:#43a047;color:#1b5e20;\"><b>✓ Success:</b> <%= msg %></div>\n<% } %>\n<% if (error) { %>\n<div class=\"warn\"><b>⚠ Error:</b> <%= error %></div>\n<% } %>\n\n<div class=\"builder-header card\" style=\"margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px\">\n  <div>\n    <h2 style=\"margin:0 0 4px;border:none;padding:0\">Construction Task Input &amp; Schedule Builder</h2>\n    <div class=\"sub\" style=\"color:var(--muted);font-size:12px\">Input construction tasks with explicit start and end dates to build or modify the initial CPM schedule data structure.</div>\n  </div>\n  <div style=\"display:flex;gap:8px;align-items:center;flex-wrap:wrap\">\n    <form method=\"post\" action=\"/builder/template\" style=\"display:inline-flex;gap:6px;align-items:center\">\n      <label style=\"font-size:11px;text-transform:uppercase;color:var(--muted)\">Presets:\n        <select name=\"template\" onchange=\"this.form.submit()\" style=\"font-size:12px;padding:3px 6px\">\n          <option value=\"\" disabled selected>Load Template...</option>\n          <option value=\"g0_building\">G+0 Single Story (1 level)</option>\n          <option value=\"g2_building\">G+2 Low-Rise (3 levels)</option>\n          <option value=\"g3_case_study\">G+3 Case Study (4 levels, default)</option>\n          <option value=\"g5_building\">G+5 Mid-Rise (6 levels)</option>\n          <option value=\"g10_tower\">G+10 High-Rise Tower (11 levels)</option>\n          <option value=\"g20_skyscraper\">G+20 Skyscraper (21 levels)</option>\n          <option value=\"b1_g10_tower\">B1+G+10 Tower with Basement (12 levels)</option>\n          <option value=\"substructure\">Foundation &amp; Substructure (14 tasks)</option>\n          <option value=\"commercial_warehouse\">Steel Warehouse (8 tasks)</option>\n        </select>\n      </label>\n    </form>\n    <form method=\"post\" action=\"/builder/reset\" style=\"display:inline\" onsubmit=\"return confirm('Reset all tasks to the synthetic G+3 building case study?')\">\n      <button type=\"submit\" class=\"alt\" style=\"font-size:12px;padding:4px 10px\">Reset to Case Study</button>\n    </form>\n    <form method=\"post\" action=\"/builder/clear\" style=\"display:inline\" onsubmit=\"return confirm('Clear ALL tasks to start a fresh custom schedule?')\">\n      <button type=\"submit\" class=\"alt\" style=\"font-size:12px;padding:4px 10px;color:var(--critical);border-color:var(--critical)\">Clear All</button>\n    </form>\n    <a href=\"/gantt<%= query ? '?' + query : '' %>\" class=\"btn\" style=\"font-size:12px;padding:5px 12px\">View Gantt Chart →</a>\n  </div>\n</div>\n\n<!-- Dynamic G+N Building Height Configuration Card -->\n<div class=\"card\" style=\"margin-bottom:14px;background:#fcfdfe;border:1px solid #c7d2fe\">\n  <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;border-bottom:1px solid #e0e7ff;padding-bottom:10px;margin-bottom:12px\">\n    <div>\n      <div style=\"display:flex;align-items:center;gap:8px\">\n        <b style=\"font-size:14px;color:#1e3a8a\">🏢 Dynamic Building Height &amp; Floor Generator (G+N)</b>\n        <span class=\"chip\" style=\"background:#dbeafe;color:#1e40af;font-weight:700\">Active: <%= (c.project && c.project.building_config && c.project.building_config.config_label) ? c.project.building_config.config_label : 'G+3' %></span>\n      </div>\n      <div style=\"font-size:12px;color:var(--muted);margin-top:2px\">\n        Configure any number of above-ground floors (G+0 to G+60), optional basements, construction method, and generate complete pipelined structural, MEP, and architectural CPM schedules.\n      </div>\n    </div>\n    <div style=\"font-size:11.5px;color:var(--muted)\">\n      <b><%= c.project ? c.project.activity_count : 0 %></b> activities · <b><%= c.project ? c.project.dependency_count : 0 %></b> dependencies\n    </div>\n  </div>\n\n  <form method=\"post\" action=\"/builder/generate-floors\" id=\"gn-floor-form\">\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(140px, 1fr));gap:12px;align-items:end\">\n      <label style=\"font-size:12px;font-weight:600;color:var(--ink)\">\n        Ground Floor (G)\n        <div style=\"margin-top:6px;display:flex;align-items:center;gap:6px;font-weight:normal;height:32px\">\n          <input type=\"checkbox\" name=\"has_ground_floor\" id=\"gn-has-ground\" <%= (!c.project || !c.project.building_config || c.project.building_config.has_ground_floor !== false) ? 'checked' : '' %>>\n          <span style=\"font-size:12px\">Include Ground Floor</span>\n        </div>\n      </label>\n\n      <label style=\"font-size:12px;font-weight:600;color:var(--ink)\">\n        Floors Above Ground (N)\n        <input type=\"number\" name=\"floors_above_ground\" id=\"gn-floors-above\" min=\"0\" max=\"60\" required \n               value=\"<%= (c.project && c.project.building_config && typeof c.project.building_config.floors_above_ground === 'number') ? c.project.building_config.floors_above_ground : 3 %>\"\n               style=\"width:100%;font-size:13px;padding:5px 8px;margin-top:4px\" />\n      </label>\n\n      <label style=\"font-size:12px;font-weight:600;color:var(--ink)\">\n        Basement Levels (B)\n        <input type=\"number\" name=\"basement_floors\" id=\"gn-basements\" min=\"0\" max=\"5\" required \n               value=\"<%= (c.project && c.project.building_config && typeof c.project.building_config.basement_floors === 'number') ? c.project.building_config.basement_floors : 0 %>\"\n               style=\"width:100%;font-size:13px;padding:5px 8px;margin-top:4px\" />\n      </label>\n\n      <label style=\"font-size:12px;font-weight:600;color:var(--ink)\">\n        Building Type\n        <select name=\"building_type\" id=\"gn-bldg-type\" style=\"width:100%;font-size:12.5px;padding:5px 8px;margin-top:4px\">\n          <% const curType = (c.project && c.project.building_config && c.project.building_config.building_type) || 'residential'; %>\n          <option value=\"residential\" <%= curType === 'residential' ? 'selected' : '' %>>Residential High-Rise</option>\n          <option value=\"commercial\" <%= curType === 'commercial' ? 'selected' : '' %>>Commercial Office</option>\n          <option value=\"mixed_use\" <%= curType === 'mixed_use' ? 'selected' : '' %>>Mixed-Use Tower</option>\n          <option value=\"industrial\" <%= curType === 'industrial' ? 'selected' : '' %>>Industrial Facility</option>\n        </select>\n      </label>\n\n      <label style=\"font-size:12px;font-weight:600;color:var(--ink)\">\n        Construction Method\n        <select name=\"construction_method\" id=\"gn-method\" style=\"width:100%;font-size:12.5px;padding:5px 8px;margin-top:4px\">\n          <% const curMethod = (c.project && c.project.building_config && c.project.building_config.construction_method) || 'rcc_framed'; %>\n          <option value=\"rcc_framed\" <%= curMethod === 'rcc_framed' ? 'selected' : '' %>>RCC Cast-In-Situ Framed</option>\n          <option value=\"precast_concrete\" <%= curMethod === 'precast_concrete' ? 'selected' : '' %>>Precast Modular Concrete</option>\n          <option value=\"steel_composite\" <%= curMethod === 'steel_composite' ? 'selected' : '' %>>Structural Steel Composite</option>\n        </select>\n      </label>\n\n      <div>\n        <button type=\"submit\" class=\"btn\" style=\"width:100%;height:32px;font-size:12px;background:#2563eb;color:#fff;border-color:#1d4ed8;font-weight:600\">\n          ⚡ Generate G+N Schedule\n        </button>\n      </div>\n    </div>\n\n    <!-- Quick configuration presets -->\n    <div style=\"margin-top:10px;padding-top:8px;border-top:1px dashed #dbeafe;display:flex;align-items:center;flex-wrap:wrap;gap:6px\">\n      <span style=\"font-size:11px;color:var(--muted);text-transform:uppercase;font-weight:600\">Quick Height Presets:</span>\n      <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"setHeightPreset(true, 0, 0)\">G+0 (1 Level)</button>\n      <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"setHeightPreset(true, 2, 0)\">G+2 (3 Levels)</button>\n      <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"setHeightPreset(true, 3, 0)\">G+3 (4 Levels)</button>\n      <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"setHeightPreset(true, 5, 0)\">G+5 (6 Levels)</button>\n      <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"setHeightPreset(true, 10, 0)\">G+10 (11 Levels)</button>\n      <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"setHeightPreset(true, 20, 0)\">G+20 (21 Levels)</button>\n      <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"setHeightPreset(true, 10, 1)\">B1+G+10 (12 Levels)</button>\n    </div>\n  </form>\n</div>\n\n<div class=\"grid g2\" style=\"align-items:start\">\n  <!-- FORM COMPONENT -->\n  <div class=\"card form-card\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:8px;margin-bottom:12px\">\n      <b id=\"form-title\" style=\"font-size:14px;color:var(--ink)\">＋ Add Construction Task</b>\n      <span id=\"edit-badge\" class=\"chip\" style=\"display:none;background:var(--accent)\">Editing <span id=\"edit-id-display\"></span></span>\n    </div>\n\n    <!-- Live Working Days Date Calculation Badge -->\n    <div id=\"calc-preview\" style=\"background:#f4f6fa;border:1px solid #d0d7de;border-radius:3px;padding:8px 12px;margin-bottom:12px;font-size:12px;display:flex;align-items:center;justify-content:space-between;gap:8px\">\n      <div>\n        <span style=\"color:var(--muted)\">Working Duration:</span>\n        <b id=\"calc-wd\" style=\"color:var(--blue);font-size:14px;margin-left:4px\">5 working days</b>\n      </div>\n      <div style=\"color:var(--muted);font-size:11.5px\">\n        <span id=\"calc-span\">6 cal. days</span> · <span id=\"calc-monsoon\">0% monsoon</span>\n      </div>\n    </div>\n\n    <form id=\"task-form\" method=\"post\" action=\"/builder/add\">\n      <div class=\"form-section\">\n        <div class=\"section-title\">Task Identification</div>\n        <div class=\"form-row r4\">\n          <label>Task ID\n            <input type=\"text\" id=\"inp-id\" name=\"activity_id\" placeholder=\"e.g. A010\" title=\"Leave empty to auto-generate next ID\">\n          </label>\n          <label>WBS Code\n            <input type=\"text\" id=\"inp-wbs\" name=\"wbs\" placeholder=\"1.1\" value=\"1.0\">\n          </label>\n          <label style=\"grid-column:span 2\">Task Name / Description *\n            <input type=\"text\" id=\"inp-name\" name=\"name\" required placeholder=\"e.g. Footing reinforcement & formwork\">\n          </label>\n        </div>\n\n        <div class=\"form-row r2\" style=\"margin-top:8px\">\n          <label>Activity Type\n            <select id=\"inp-type\" name=\"activity_type\">\n              <option value=\"SUBSTRUCTURE\">SUBSTRUCTURE (Earthwork, Foundations, Plinth)</option>\n              <option value=\"STRUCTURE\" selected>STRUCTURE (Columns, Beams, Slabs)</option>\n              <option value=\"MASONRY\">MASONRY (Brickwork, Blockwork, Lintels)</option>\n              <option value=\"MEP\">MEP (Plumbing, Electrical, HVAC)</option>\n              <option value=\"FINISH\">FINISH (Plastering, Flooring, Painting)</option>\n              <option value=\"EXTERNAL\">EXTERNAL (Site works, Paving, Landscaping)</option>\n            </select>\n          </label>\n          <label>Predecessors (Dependencies)\n            <input type=\"text\" id=\"inp-preds\" name=\"predecessors\" placeholder=\"e.g. A010, A020:SS2, A030:FS1\">\n          </label>\n        </div>\n      </div>\n\n      <div class=\"form-section\" style=\"margin-top:12px\">\n        <div class=\"section-title\">Schedule Window (Start &amp; End Dates)</div>\n        <div class=\"form-row r2\">\n          <label>Planned Start Date *\n            <input type=\"date\" id=\"inp-start\" name=\"start_date\" required value=\"<%= c ? c.data_date : '2026-05-04' %>\">\n          </label>\n          <label>Planned End Date *\n            <input type=\"date\" id=\"inp-end\" name=\"end_date\" required value=\"<%= c ? c.data_date : '2026-05-09' %>\">\n          </label>\n        </div>\n        <div class=\"note\" style=\"margin-top:4px;font-size:11px\">\n          The engine calculates integer working days automatically using the project's 6-day work calendar and site holidays.\n        </div>\n      </div>\n\n      <div class=\"form-section\" style=\"margin-top:12px\">\n        <div class=\"section-title\">Resource &amp; Cost Parameters</div>\n        <div class=\"form-row r3\">\n          <label>Trade Resource\n            <select id=\"inp-res\" name=\"resource\">\n              <option value=\"HELPER\">HELPER (Helpers / general labour)</option>\n              <option value=\"MASON\">MASON (Masons)</option>\n              <option value=\"CARP\">CARP (Carpenters)</option>\n              <option value=\"BARB\">BARB (Bar benders)</option>\n              <option value=\"MIXER\">MIXER (Concrete mixers / pumps)</option>\n              <option value=\"EXC\">EXC (Excavators with operator)</option>\n              <option value=\"ELEC\">ELEC (Electricians)</option>\n              <option value=\"PLUM\">PLUM (Plumbers)</option>\n              <option value=\"PAINT\">PAINT (Painters)</option>\n              <option value=\"TILER\">TILER (Tilers)</option>\n            </select>\n          </label>\n          <label>Crew Size\n            <input type=\"number\" id=\"inp-crew\" name=\"crew_size\" min=\"1\" max=\"100\" value=\"6\">\n          </label>\n          <label>Quantity &amp; Unit\n            <div style=\"display:flex;gap:4px\">\n              <input type=\"number\" id=\"inp-qty\" name=\"quantity\" step=\"any\" placeholder=\"Qty\" value=\"100\" style=\"width:65%\">\n              <input type=\"text\" id=\"inp-unit\" name=\"unit\" placeholder=\"m3\" value=\"m3\" style=\"width:35%\">\n            </div>\n          </label>\n        </div>\n\n        <div class=\"form-row r3\" style=\"margin-top:8px\">\n          <label>Normal Cost (INR)\n            <input type=\"number\" id=\"inp-cost\" name=\"normal_cost\" min=\"0\" placeholder=\"0\" value=\"50000\">\n          </label>\n          <label>Crash Duration (wd)\n            <input type=\"number\" id=\"inp-crash-dur\" name=\"crash_duration\" min=\"1\" placeholder=\"Optional\">\n          </label>\n          <label>Crash Cost (INR)\n            <input type=\"number\" id=\"inp-crash-cost\" name=\"crash_cost\" min=\"0\" placeholder=\"Optional\">\n          </label>\n        </div>\n\n        <div class=\"form-row r2\" style=\"margin-top:8px\">\n          <label>Progress Complete (%)\n            <input type=\"number\" id=\"inp-prog\" name=\"percent_complete\" min=\"0\" max=\"100\" step=\"5\" value=\"0\">\n          </label>\n          <label>Observed Delay Days\n            <input type=\"number\" id=\"inp-delay\" name=\"actual_delay_days\" min=\"0\" value=\"0\" placeholder=\"0\">\n          </label>\n        </div>\n      </div>\n\n      <div style=\"display:flex;gap:8px;margin-top:16px;align-items:center\">\n        <button type=\"submit\" id=\"btn-submit\" style=\"flex:1;background:var(--blue);border-color:var(--blue);font-weight:600\">＋ Add Task to Schedule</button>\n        <button type=\"button\" id=\"btn-cancel\" class=\"alt\" onclick=\"resetForm()\" style=\"display:none\">Cancel Edit</button>\n      </div>\n    </form>\n  </div>\n\n  <!-- SCHEDULE KPIS & QUICK TOOLS -->\n  <div>\n    <div class=\"card\">\n      <b>Current Schedule Architecture</b>\n      <div class=\"grid g2\" style=\"margin-top:10px;gap:8px\">\n        <div style=\"background:#faf8f2;padding:8px;border:1px solid var(--line)\">\n          <div style=\"font-size:10.5px;color:var(--muted);text-transform:uppercase\">Total Activities</div>\n          <div style=\"font-size:22px;font-weight:600\" class=\"mono\"><%= c ? c.project.activity_count : 0 %></div>\n          <div style=\"font-size:11px;color:var(--muted)\"><%= c ? c.project.dependency_count : 0 %> dependency links</div>\n        </div>\n        <div style=\"background:#faf8f2;padding:8px;border:1px solid var(--line)\">\n          <div style=\"font-size:10.5px;color:var(--muted);text-transform:uppercase\">Project Duration</div>\n          <div style=\"font-size:22px;font-weight:600\" class=\"mono\"><%= c && c.kpis ? c.kpis.baseline_duration_wd : 0 %> <span style=\"font-size:13px;font-weight:normal\">wd</span></div>\n          <div style=\"font-size:11px;color:var(--muted)\">finishes <%= c && c.kpis ? c.kpis.baseline_completion : '–' %></div>\n        </div>\n        <div style=\"background:#faf8f2;padding:8px;border:1px solid var(--line)\">\n          <div style=\"font-size:10.5px;color:var(--muted);text-transform:uppercase\">Critical Path</div>\n          <div style=\"font-size:22px;font-weight:600\" class=\"mono\"><%= c && c.kpis ? c.kpis.critical_activities : 0 %> <span style=\"font-size:13px;font-weight:normal\">tasks</span></div>\n          <div style=\"font-size:11px;color:var(--critical)\">Zero total float</div>\n        </div>\n        <div style=\"background:#faf8f2;padding:8px;border:1px solid var(--line)\">\n          <div style=\"font-size:10.5px;color:var(--muted);text-transform:uppercase\">Near-Critical Tasks</div>\n          <div style=\"font-size:22px;font-weight:600\" class=\"mono\"><%= c && c.kpis ? c.kpis.near_critical_count : 0 %></div>\n          <div style=\"font-size:11px;color:var(--muted)\">0 &lt; Float ≤ 5 wd</div>\n        </div>\n      </div>\n      <div style=\"margin-top:12px;font-size:12px;color:var(--muted);line-height:1.5\">\n        <b>How CPM Schedule Building Works:</b> Tasks are structured with working day windows. Setting predecessors creates FS/SS/FF/SF constraints. The engine computes early and late dates, floats, and isolates the critical path.\n      </div>\n    </div>\n\n    <!-- Quick Predecessor Helper Card -->\n    <div class=\"card\" style=\"margin-top:12px\">\n      <b>Quick Dependency Helper</b>\n      <div style=\"font-size:12px;color:var(--muted);margin:4px 0 8px\">Select an existing activity to insert into the Predecessors input:</div>\n      <div style=\"display:flex;gap:6px\">\n        <select id=\"pred-selector\" style=\"flex:1;font-size:12px\">\n          <option value=\"\">Choose task to link...</option>\n          <% if (c && c.activities) { %>\n            <% c.activities.forEach(function(a) { %>\n              <option value=\"<%= a.activity_id %>\"><%= a.activity_id %>: <%= a.name %> (<%= a.current_duration %> wd)</option>\n            <% }); %>\n          <% } %>\n        </select>\n        <select id=\"pred-type-sel\" style=\"width:80px;font-size:12px\">\n          <option value=\"FS\">FS (Finish-Start)</option>\n          <option value=\"SS\">SS (Start-Start)</option>\n          <option value=\"FF\">FF (Finish-Finish)</option>\n          <option value=\"SF\">SF (Start-Finish)</option>\n        </select>\n        <input type=\"number\" id=\"pred-lag-sel\" placeholder=\"Lag\" value=\"0\" style=\"width:50px;font-size:12px\">\n        <button type=\"button\" class=\"alt\" onclick=\"addPredHelper()\" style=\"padding:4px 8px;font-size:12px\">+ Link</button>\n      </div>\n    </div>\n\n    <!-- CUSTOM VALUE SLOT COMPONENT -->\n    <div class=\"card slot-card\" id=\"custom-slot-section\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px\">\n        <b style=\"color:var(--ink);font-size:13px\">⚡ Custom Value Slot (Quick / Batch Input)</b>\n        <span class=\"note\" style=\"font-size:11px\">Paste or enter your custom values</span>\n      </div>\n      <p class=\"note\" style=\"margin:0 0 8px;font-size:11.5px\">\n        Type your own values below (one task per line). Format: <code>Task Name, Start Date, End Date, [Type], [Resource], [Crew], [Cost], [Predecessors]</code>\n      </p>\n\n      <form method=\"post\" action=\"/builder/batch\" id=\"slot-batch-form\">\n        <textarea name=\"slot_text\" id=\"slot-text\" rows=\"3\" class=\"slot-textarea\" placeholder=\"Tower Crane Foundation, 2026-05-18, 2026-05-26, SUBSTRUCTURE, MASON, 8, 75000, A020\nUnderground Stormwater Tank, 2026-05-26, 2026-06-06, SUBSTRUCTURE, EXC, 4, 90000, A030\"></textarea>\n        <div style=\"display:flex;gap:6px;margin-top:8px;flex-wrap:wrap\">\n          <button type=\"submit\" style=\"font-size:12px;padding:5px 12px;background:var(--blue);border-color:var(--blue)\">⚡ Import Slot Tasks into Schedule</button>\n          <button type=\"button\" class=\"alt\" style=\"font-size:12px;padding:5px 10px\" onclick=\"transferSlotToMainForm()\">⟵ Fill Form from Slot</button>\n          <button type=\"button\" class=\"alt\" style=\"font-size:12px;padding:5px 10px\" onclick=\"document.getElementById('slot-text').value=''\">Clear Slot</button>\n        </div>\n      </form>\n    </div>\n\n    <!-- EXAMPLE CASES BELOW THE SLOT -->\n    <div class=\"example-cases-container\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin:14px 0 8px\">\n        <b style=\"font-size:13px;color:var(--ink)\">📚 Construction Example Cases</b>\n        <span class=\"note\" style=\"font-size:11px\">Click to load into slot or add directly</span>\n      </div>\n\n      <!-- Example Case 1 -->\n      <div class=\"example-case-card\">\n        <div class=\"example-case-header\">\n          <b style=\"font-size:12.5px;color:var(--ink)\">1. Deep Shoring &amp; Bulk Excavation</b>\n          <span class=\"chip low\" style=\"font-size:10px\">SUBSTRUCTURE</span>\n        </div>\n        <div class=\"example-case-meta\">\n          <span>2026-05-18 → 2026-05-28 (9 wd)</span>\n          <span>EXC (4 crew)</span>\n          <span>1,200 m3</span>\n          <span>₹85,000</span>\n          <span>Pred: A020</span>\n        </div>\n        <div class=\"note\" style=\"font-size:11px;margin-bottom:8px\">Heavy earthmoving and retaining shoring for basement footings with excavator operators.</div>\n        <div class=\"example-case-actions\">\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"loadExampleCase(0, false)\">↳ Load into Slot &amp; Form</button>\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px;color:var(--blue);border-color:var(--blue)\" onclick=\"loadExampleCase(0, true)\">＋ Add to Schedule</button>\n        </div>\n      </div>\n\n      <!-- Example Case 2 -->\n      <div class=\"example-case-card\">\n        <div class=\"example-case-header\">\n          <b style=\"font-size:12.5px;color:var(--ink)\">2. 2nd Floor Monolithic Slab &amp; Beam Pour</b>\n          <span class=\"chip medium\" style=\"font-size:10px\">STRUCTURE</span>\n        </div>\n        <div class=\"example-case-meta\">\n          <span>2026-06-08 → 2026-06-18 (9 wd)</span>\n          <span>MIXER (6 crew)</span>\n          <span>220 m3</span>\n          <span>₹180,000</span>\n          <span>Pred: A240</span>\n        </div>\n        <div class=\"note\" style=\"font-size:11px;margin-bottom:8px\">Staged structural RCC slab concreting with stationary pump and compaction crew.</div>\n        <div class=\"example-case-actions\">\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"loadExampleCase(1, false)\">↳ Load into Slot &amp; Form</button>\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px;color:var(--blue);border-color:var(--blue)\" onclick=\"loadExampleCase(1, true)\">＋ Add to Schedule</button>\n        </div>\n      </div>\n\n      <!-- Example Case 3 -->\n      <div class=\"example-case-card\">\n        <div class=\"example-case-header\">\n          <b style=\"font-size:12.5px;color:var(--ink)\">3. Monsoon Exposed Basement Waterproofing</b>\n          <span class=\"chip critical\" style=\"font-size:10px\">SUBSTRUCTURE</span>\n        </div>\n        <div class=\"example-case-meta\">\n          <span>2026-07-13 → 2026-07-25 (11 wd)</span>\n          <span>HELPER (8 crew)</span>\n          <span>650 m2</span>\n          <span>₹70,000</span>\n          <span>Pred: A120</span>\n        </div>\n        <div class=\"note\" style=\"font-size:11px;margin-bottom:8px\">Peak monsoon scheduled task testing weather risk prediction &amp; rainwater dewatering.</div>\n        <div class=\"example-case-actions\">\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"loadExampleCase(2, false)\">↳ Load into Slot &amp; Form</button>\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px;color:var(--blue);border-color:var(--blue)\" onclick=\"loadExampleCase(2, true)\">＋ Add to Schedule</button>\n        </div>\n      </div>\n\n      <!-- Example Case 4 -->\n      <div class=\"example-case-card\">\n        <div class=\"example-case-header\">\n          <b style=\"font-size:12.5px;color:var(--ink)\">4. Vertical Plumbing Risers &amp; Drainage Stacks</b>\n          <span class=\"chip high\" style=\"font-size:10px\">MEP</span>\n        </div>\n        <div class=\"example-case-meta\">\n          <span>2026-07-06 → 2026-07-16 (9 wd)</span>\n          <span>PLUM (6 crew)</span>\n          <span>1 LS</span>\n          <span>₹95,000</span>\n          <span>Pred: A190:FS4</span>\n        </div>\n        <div class=\"note\" style=\"font-size:11px;margin-bottom:8px\">Multi-floor cast iron soil stacks, vents, and pressure testing across vertical ducts.</div>\n        <div class=\"example-case-actions\">\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"loadExampleCase(3, false)\">↳ Load into Slot &amp; Form</button>\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px;color:var(--blue);border-color:var(--blue)\" onclick=\"loadExampleCase(3, true)\">＋ Add to Schedule</button>\n        </div>\n      </div>\n\n      <!-- Example Case 5 -->\n      <div class=\"example-case-card\">\n        <div class=\"example-case-header\">\n          <b style=\"font-size:12.5px;color:var(--ink)\">5. High-Voltage Substation &amp; Busduct Conduit</b>\n          <span class=\"chip medium\" style=\"font-size:10px\">MEP</span>\n        </div>\n        <div class=\"example-case-meta\">\n          <span>2026-08-10 → 2026-08-22 (11 wd)</span>\n          <span>ELEC (8 crew)</span>\n          <span>1 LS</span>\n          <span>₹140,000</span>\n          <span>Pred: A310:FS2</span>\n        </div>\n        <div class=\"note\" style=\"font-size:11px;margin-bottom:8px\">Main distribution boards, busducts, and transformer tie-ins with certified technicians.</div>\n        <div class=\"example-case-actions\">\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"loadExampleCase(4, false)\">↳ Load into Slot &amp; Form</button>\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px;color:var(--blue);border-color:var(--blue)\" onclick=\"loadExampleCase(4, true)\">＋ Add to Schedule</button>\n        </div>\n      </div>\n\n      <!-- Example Case 6 -->\n      <div class=\"example-case-card\">\n        <div class=\"example-case-header\">\n          <b style=\"font-size:12.5px;color:var(--ink)\">6. Vitrified Floor Tiling &amp; Skirting Finishes</b>\n          <span class=\"chip low\" style=\"font-size:10px\">FINISH</span>\n        </div>\n        <div class=\"example-case-meta\">\n          <span>2026-09-01 → 2026-09-15 (12 wd)</span>\n          <span>TILER (10 crew)</span>\n          <span>850 m2</span>\n          <span>₹120,000</span>\n          <span>Pred: A370</span>\n        </div>\n        <div class=\"note\" style=\"font-size:11px;margin-bottom:8px\">Laser-level bedding mortar, 600x600 vitrified tile laying, epoxy grouting &amp; skirting.</div>\n        <div class=\"example-case-actions\">\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" onclick=\"loadExampleCase(5, false)\">↳ Load into Slot &amp; Form</button>\n          <button type=\"button\" class=\"btn alt\" style=\"font-size:11px;padding:2px 8px;color:var(--blue);border-color:var(--blue)\" onclick=\"loadExampleCase(5, true)\">＋ Add to Schedule</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- SCHEDULE DATA STRUCTURE TABLE -->\n<div style=\"margin-top:20px\">\n  <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex-wrap:wrap;gap:8px\">\n    <h2 style=\"margin:0;border:none;padding:0\">Defined Construction Tasks in Schedule Structure (<%= c && c.activities ? c.activities.length : 0 %>)</h2>\n    <div style=\"display:flex;gap:10px;align-items:center;flex-wrap:wrap\">\n      <input type=\"text\" id=\"task-search\" placeholder=\"Search tasks...\" oninput=\"filterTable()\" style=\"font-size:12px;padding:4px 8px;width:160px\">\n      <select id=\"floor-filter\" onchange=\"filterTable()\" style=\"font-size:12px;padding:4px 8px\">\n        <option value=\"all\">All Floors</option>\n        <% if (c.project && c.project.floors) { %>\n          <% c.project.floors.forEach(function(fl) { %>\n            <option value=\"<%= fl %>\"><%= fl %></option>\n          <% }); %>\n        <% } %>\n      </select>\n      <select id=\"type-filter\" onchange=\"filterTable()\" style=\"font-size:12px;padding:4px 8px\">\n        <option value=\"all\">All Types</option>\n        <option value=\"SUBSTRUCTURE\">Substructure</option>\n        <option value=\"STRUCTURE\">Structure</option>\n        <option value=\"MASONRY\">Masonry</option>\n        <option value=\"MEP\">MEP</option>\n        <option value=\"FINISH\">Finish</option>\n        <option value=\"EXTERNAL\">External</option>\n      </select>\n      <label style=\"font-size:12px;display:flex;align-items:center;gap:4px;cursor:pointer\">\n        <input type=\"checkbox\" id=\"crit-only\" onchange=\"filterTable()\"> Critical Only\n      </label>\n    </div>\n  </div>\n\n  <div class=\"scroll\" style=\"max-height:60vh\">\n    <table id=\"tasks-table\">\n      <thead>\n        <tr>\n          <th>ID</th>\n          <th>Floor</th>\n          <th>WBS</th>\n          <th>Task Name</th>\n          <th>Type</th>\n          <th>Start Date</th>\n          <th>End Date</th>\n          <th class=\"num\">Duration</th>\n          <th>Predecessors</th>\n          <th>Resource &amp; Crew</th>\n          <th class=\"num\">Float</th>\n          <th>Status</th>\n          <th style=\"text-align:center\">Actions</th>\n        </tr>\n      </thead>\n      <tbody>\n        <% if (c && c.activities && c.activities.length > 0) { %>\n          <% c.activities.forEach(function(a) { %>\n            <tr id=\"row-<%= a.activity_id %>\" data-type=\"<%= a.type %>\" data-floor=\"<%= a.floor || '' %>\" data-critical=\"<%= a.critical ? '1' : '0' %>\">\n              <td><b class=\"mono\"><%= a.activity_id %></b></td>\n              <td><span class=\"chip\" style=\"font-size:10px;font-weight:600\"><%= a.floor || '–' %></span></td>\n              <td class=\"mono\"><%= a.wbs %></td>\n              <td>\n                <div style=\"font-weight:500\"><%= a.name %></div>\n                <% if (a.percent_complete > 0) { %>\n                  <div style=\"font-size:10.5px;color:var(--muted)\">Progress: <%= a.percent_complete %>%<%= a.injected_days > 0 ? ` · ${a.injected_days}d delay` : '' %></div>\n                <% } %>\n              </td>\n              <td><span class=\"chip <%= a.risk_band || 'medium' %>\" style=\"font-size:10px;text-transform:lowercase\"><%= a.type %></span></td>\n              <td class=\"mono\"><%= a.baseline_start %></td>\n              <td class=\"mono\"><%= a.baseline_finish %></td>\n              <td class=\"num\"><%= a.planned_duration %> wd</td>\n              <td class=\"mono\" style=\"font-size:11px\"><%= a.predecessors || '–' %></td>\n              <td><%= a.resource %> (<%= a.crew_size %>)</td>\n              <td class=\"num <%= a.critical ? 'bad' : '' %>\"><%= a.total_float %> wd</td>\n              <td>\n                <% if (a.critical) { %>\n                  <span class=\"tag\">CRITICAL</span>\n                <% } else if (a.near_critical) { %>\n                  <span style=\"font-size:11px;color:var(--high);font-weight:600\">NEAR</span>\n                <% } else { %>\n                  <span style=\"font-size:11px;color:var(--muted)\">Normal</span>\n                <% } %>\n              </td>\n              <td style=\"text-align:center;white-space:nowrap\">\n                <button type=\"button\" class=\"btn alt\" style=\"padding:2px 8px;font-size:11px\" onclick=\"editTask(<%= JSON.stringify(a) %>)\">Edit</button>\n                <form method=\"post\" action=\"/builder/delete/<%= a.activity_id %>\" style=\"display:inline\" onsubmit=\"return confirm('Delete activity <%= a.activity_id %>?')\">\n                  <button type=\"submit\" class=\"btn alt\" style=\"padding:2px 6px;font-size:11px;color:var(--critical);border-color:var(--critical)\">✕</button>\n                </form>\n              </td>\n            </tr>\n          <% }); %>\n        <% } else { %>\n          <tr>\n            <td colspan=\"12\" style=\"text-align:center;padding:24px;color:var(--muted)\">\n              No tasks currently defined. Use the form above to add your first construction task, or select a preset template!\n            </td>\n          </tr>\n        <% } %>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n<script>\n(function() {\n  const form = document.getElementById('task-form');\n  const formTitle = document.getElementById('form-title');\n  const btnSubmit = document.getElementById('btn-submit');\n  const btnCancel = document.getElementById('btn-cancel');\n  const editBadge = document.getElementById('edit-badge');\n  const editIdDisplay = document.getElementById('edit-id-display');\n\n  const inpId = document.getElementById('inp-id');\n  const inpWbs = document.getElementById('inp-wbs');\n  const inpName = document.getElementById('inp-name');\n  const inpType = document.getElementById('inp-type');\n  const inpStart = document.getElementById('inp-start');\n  const inpEnd = document.getElementById('inp-end');\n  const inpPreds = document.getElementById('inp-preds');\n  const inpRes = document.getElementById('inp-res');\n  const inpCrew = document.getElementById('inp-crew');\n  const inpQty = document.getElementById('inp-qty');\n  const inpUnit = document.getElementById('inp-unit');\n  const inpCost = document.getElementById('inp-cost');\n  const inpCrashDur = document.getElementById('inp-crash-dur');\n  const inpCrashCost = document.getElementById('inp-crash-cost');\n  const inpProg = document.getElementById('inp-prog');\n  const inpDelay = document.getElementById('inp-delay');\n\n  const calcWd = document.getElementById('calc-wd');\n  const calcSpan = document.getElementById('calc-span');\n  const calcMonsoon = document.getElementById('calc-monsoon');\n\n  // Live working days computation on date input change\n  let timer = null;\n  function updateLiveWorkingDays() {\n    clearTimeout(timer);\n    timer = setTimeout(async () => {\n      const s = inpStart.value;\n      const e = inpEnd.value;\n      if (!s || !e) return;\n      try {\n        const res = await fetch(`/api/calendar/calc-days?start_date=${s}&end_date=${e}`);\n        if (res.ok) {\n          const data = await res.json();\n          calcWd.textContent = `${data.working_days} working days`;\n          calcSpan.textContent = `${data.calendar_days} cal. days`;\n          calcMonsoon.textContent = `${Math.round(data.monsoon_exposure * 100)}% monsoon`;\n        }\n      } catch (err) {\n        console.error(err);\n      }\n    }, 150);\n  }\n\n  inpStart.addEventListener('change', updateLiveWorkingDays);\n  inpEnd.addEventListener('change', updateLiveWorkingDays);\n  updateLiveWorkingDays();\n\n  // Populate form for editing\n  window.editTask = function(task) {\n    form.action = '/builder/update/' + encodeURIComponent(task.activity_id);\n    formTitle.textContent = '✎ Edit Construction Task';\n    btnSubmit.textContent = '✓ Save Changes to ' + task.activity_id;\n    btnSubmit.style.background = 'var(--accent)';\n    btnSubmit.style.borderColor = 'var(--accent)';\n    btnCancel.style.display = 'inline-block';\n    editBadge.style.display = 'inline-block';\n    editIdDisplay.textContent = task.activity_id;\n\n    inpId.value = task.activity_id;\n    inpId.readOnly = true;\n    inpId.style.background = '#f0ebe1';\n    inpWbs.value = task.wbs || '';\n    inpName.value = task.name || '';\n    inpType.value = task.type || 'STRUCTURE';\n    inpStart.value = task.baseline_start || task.start_date || '';\n    inpEnd.value = task.baseline_finish || task.end_date || '';\n    inpPreds.value = task.predecessors || '';\n    inpRes.value = task.resource || 'HELPER';\n    inpCrew.value = task.crew_size || 6;\n    inpQty.value = task.quantity !== undefined ? task.quantity : 100;\n    inpUnit.value = task.unit || 'm3';\n    inpCost.value = task.normal_cost !== undefined ? task.normal_cost : 50000;\n    inpCrashDur.value = task.crash_duration || '';\n    inpCrashCost.value = task.crash_cost || '';\n    inpProg.value = task.percent_complete || 0;\n    inpDelay.value = task.injected_days || task.actual_delay_days || 0;\n\n    updateLiveWorkingDays();\n    form.scrollIntoView({ behavior: 'smooth', block: 'start' });\n  };\n\n  const EXAMPLE_CASES = [\n    {\n      name: 'Deep Shoring & Bulk Excavation',\n      wbs: '1.2',\n      activity_type: 'SUBSTRUCTURE',\n      start_date: '2026-05-18',\n      end_date: '2026-05-28',\n      resource: 'EXC',\n      crew_size: 4,\n      quantity: 1200,\n      unit: 'm3',\n      normal_cost: 85000,\n      crash_duration: 6,\n      crash_cost: 115000,\n      predecessors: 'A020',\n      percent_complete: 0,\n      actual_delay_days: 0\n    },\n    {\n      name: '2nd Floor Monolithic Slab & Beam Pour',\n      wbs: '2.4',\n      activity_type: 'STRUCTURE',\n      start_date: '2026-06-08',\n      end_date: '2026-06-18',\n      resource: 'MIXER',\n      crew_size: 6,\n      quantity: 220,\n      unit: 'm3',\n      normal_cost: 180000,\n      crash_duration: 6,\n      crash_cost: 235000,\n      predecessors: 'A240',\n      percent_complete: 0,\n      actual_delay_days: 0\n    },\n    {\n      name: 'Monsoon Exposed Basement Waterproofing',\n      wbs: '1.5',\n      activity_type: 'SUBSTRUCTURE',\n      start_date: '2026-07-13',\n      end_date: '2026-07-25',\n      resource: 'HELPER',\n      crew_size: 8,\n      quantity: 650,\n      unit: 'm2',\n      normal_cost: 70000,\n      crash_duration: 8,\n      crash_cost: 92000,\n      predecessors: 'A120',\n      percent_complete: 0,\n      actual_delay_days: 0\n    },\n    {\n      name: 'Vertical Plumbing Risers & Drainage Stacks',\n      wbs: '4.2',\n      activity_type: 'MEP',\n      start_date: '2026-07-06',\n      end_date: '2026-07-16',\n      resource: 'PLUM',\n      crew_size: 6,\n      quantity: 1,\n      unit: 'LS',\n      normal_cost: 95000,\n      crash_duration: 7,\n      crash_cost: 120000,\n      predecessors: 'A190:FS4',\n      percent_complete: 0,\n      actual_delay_days: 0\n    },\n    {\n      name: 'High-Voltage Substation & Busduct Conduit',\n      wbs: '4.5',\n      activity_type: 'MEP',\n      start_date: '2026-08-10',\n      end_date: '2026-08-22',\n      resource: 'ELEC',\n      crew_size: 8,\n      quantity: 1,\n      unit: 'LS',\n      normal_cost: 140000,\n      crash_duration: 7,\n      crash_cost: 185000,\n      predecessors: 'A310:FS2',\n      percent_complete: 0,\n      actual_delay_days: 0\n    },\n    {\n      name: 'Vitrified Floor Tiling & Skirting Finishes',\n      wbs: '5.2',\n      activity_type: 'FINISH',\n      start_date: '2026-09-01',\n      end_date: '2026-09-15',\n      resource: 'TILER',\n      crew_size: 10,\n      quantity: 850,\n      unit: 'm2',\n      normal_cost: 120000,\n      crash_duration: 9,\n      crash_cost: 155000,\n      predecessors: 'A370',\n      percent_complete: 0,\n      actual_delay_days: 0\n    }\n  ];\n\n  window.loadExampleCase = function(idx, autoSubmit) {\n    const item = EXAMPLE_CASES[idx];\n    if (!item) return;\n\n    // Fill the slot textarea\n    const slotEl = document.getElementById('slot-text');\n    slotEl.value = `${item.name}, ${item.start_date}, ${item.end_date}, ${item.activity_type}, ${item.resource}, ${item.crew_size}, ${item.normal_cost}, ${item.predecessors}`;\n\n    // Fill the form fields\n    inpName.value = item.name;\n    inpWbs.value = item.wbs;\n    inpType.value = item.activity_type;\n    inpStart.value = item.start_date;\n    inpEnd.value = item.end_date;\n    inpRes.value = item.resource;\n    inpCrew.value = item.crew_size;\n    inpQty.value = item.quantity;\n    inpUnit.value = item.unit;\n    inpCost.value = item.normal_cost;\n    inpCrashDur.value = item.crash_duration || '';\n    inpCrashCost.value = item.crash_cost || '';\n    inpPreds.value = item.predecessors;\n    inpProg.value = item.percent_complete;\n    inpDelay.value = item.actual_delay_days;\n\n    updateLiveWorkingDays();\n\n    if (autoSubmit) {\n      form.action = '/builder/add';\n      form.submit();\n    } else {\n      document.getElementById('custom-slot-section').scrollIntoView({ behavior: 'smooth', block: 'start' });\n    }\n  };\n\n  window.transferSlotToMainForm = function() {\n    const raw = document.getElementById('slot-text').value.trim();\n    if (!raw) return;\n    const firstLine = raw.split(/\\r?\\n/)[0];\n    const parts = firstLine.split(/[,\\t]/).map(p => p.trim());\n    if (parts.length >= 3) {\n      inpName.value = parts[0];\n      inpStart.value = parts[1];\n      inpEnd.value = parts[2];\n      if (parts[3]) inpType.value = parts[3].toUpperCase();\n      if (parts[4]) inpRes.value = parts[4].toUpperCase();\n      if (parts[5]) inpCrew.value = parseInt(parts[5], 10) || 4;\n      if (parts[6]) inpCost.value = parseFloat(parts[6]) || 50000;\n      if (parts[7]) inpPreds.value = parts[7];\n      if (parts[8]) inpWbs.value = parts[8];\n      updateLiveWorkingDays();\n      form.scrollIntoView({ behavior: 'smooth', block: 'start' });\n    }\n  };\n\n  window.resetForm = function() {\n    form.action = '/builder/add';\n    formTitle.textContent = '＋ Add Construction Task';\n    btnSubmit.textContent = '＋ Add Task to Schedule';\n    btnSubmit.style.background = 'var(--blue)';\n    btnSubmit.style.borderColor = 'var(--blue)';\n    btnCancel.style.display = 'none';\n    editBadge.style.display = 'none';\n\n    inpId.value = '';\n    inpId.readOnly = false;\n    inpId.style.background = '#fff';\n    inpName.value = '';\n    inpPreds.value = '';\n    updateLiveWorkingDays();\n  };\n\n  window.addPredHelper = function() {\n    const sel = document.getElementById('pred-selector');\n    const typeSel = document.getElementById('pred-type-sel');\n    const lagSel = document.getElementById('pred-lag-sel');\n    const predId = sel.value;\n    if (!predId) return;\n\n    let linkStr = predId;\n    const type = typeSel.value;\n    const lag = parseInt(lagSel.value, 10) || 0;\n    if (type !== 'FS' || lag !== 0) {\n      linkStr += `:${type}${lag !== 0 ? lag : ''}`;\n    }\n\n    const cur = inpPreds.value.trim();\n    if (cur) {\n      const parts = cur.split(',').map(s => s.trim());\n      if (!parts.includes(linkStr)) {\n        inpPreds.value = cur + ', ' + linkStr;\n      }\n    } else {\n      inpPreds.value = linkStr;\n    }\n  };\n\n  window.setHeightPreset = function(hasGround, floorsAbove, basements) {\n    document.getElementById('gn-has-ground').checked = hasGround;\n    document.getElementById('gn-floors-above').value = floorsAbove;\n    document.getElementById('gn-basements').value = basements;\n    document.getElementById('gn-floor-form').submit();\n  };\n\n  // Filter Table\n  window.filterTable = function() {\n    const q = document.getElementById('task-search').value.toLowerCase();\n    const type = document.getElementById('type-filter').value;\n    const floor = document.getElementById('floor-filter') ? document.getElementById('floor-filter').value : 'all';\n    const critOnly = document.getElementById('crit-only').checked;\n\n    const rows = document.querySelectorAll('#tasks-table tbody tr');\n    rows.forEach(r => {\n      if (r.children.length < 5) return;\n      const text = r.textContent.toLowerCase();\n      const rType = r.dataset.type;\n      const rFloor = r.dataset.floor || '';\n      const isCrit = r.dataset.critical === '1';\n\n      const matchQ = !q || text.includes(q);\n      const matchType = type === 'all' || rType === type;\n      const matchFloor = floor === 'all' || rFloor === floor;\n      const matchCrit = !critOnly || isCrit;\n\n      r.style.display = (matchQ && matchType && matchFloor && matchCrit) ? '' : 'none';\n    });\n  };\n})();\n</script>\n\n<%- include('partials/footer') %>\n",
  "dashboard": "<%- include('partials/header') %>\n<% const k = c.kpis; %>\n<% const evm = c.analytics ? c.analytics.evm : null; %>\n<div class=\"grid g4\">\n  <div class=\"card kpi\"><div class=\"l\">Baseline completion</div><div class=\"v\" id=\"kpi-baseline-completion\"><%= k.baseline_completion %></div><div class=\"s\" id=\"kpi-baseline-duration\"><%= k.baseline_duration_wd %> working days</div></div>\n  <div class=\"card kpi\"><div class=\"l\">Current forecast</div><div class=\"v\" id=\"kpi-current-completion\"><%= k.current_completion %></div><div class=\"s\" id=\"kpi-current-duration\"><%= k.current_duration_wd %> working days</div></div>\n  <div class=\"card kpi\"><div class=\"l\">Schedule variance</div><div class=\"v <%= k.schedule_variance_wd > 0 ? 'bad' : 'ok' %>\" id=\"kpi-schedule-variance\"><%= (k.schedule_variance_wd > 0 ? '+' : '') + k.schedule_variance_wd %> wd</div><div class=\"s\" id=\"kpi-calendar-slip\"><%= (k.calendar_slip_days > 0 ? '+' : '') + k.calendar_slip_days %> calendar days</div></div>\n  <div class=\"card kpi\"><div class=\"l\">Critical-path migration</div><div class=\"v\" id=\"kpi-cpm-migration\"><%= k.critical_path_migrated ? 'YES' : 'No' %></div><div class=\"s\" id=\"kpi-cpm-details\">new: <%= k.newly_critical.join(', ') || 'none' %> · left: <%= k.left_critical.join(', ') || 'none' %></div></div>\n  <div class=\"card kpi\"><div class=\"l\">Progress (planned / actual)</div><div class=\"v\" id=\"kpi-progress\"><%= k.planned_pct.toFixed(1) %> / <%= k.actual_pct.toFixed(1) %> %</div><div class=\"s\" id=\"kpi-progress-variance\">variance <%= (k.progress_variance_pct > 0 ? '+' : '') + k.progress_variance_pct.toFixed(1) %> pts</div></div>\n  <div class=\"card kpi\"><div class=\"l\">Critical / near-critical</div><div class=\"v\" id=\"kpi-critical-counts\"><%= k.critical_activities %> / <%= k.near_critical_count %></div><div class=\"s\" id=\"kpi-float-erosion\"><%= k.eroded_float_count %> with float erosion</div></div>\n  <div class=\"card kpi\"><div class=\"l\">At-risk activities</div><div class=\"v\" id=\"kpi-at-risk-count\"><%= k.at_risk_count !== null ? k.at_risk_count : 'n/a' %></div><div class=\"s\" id=\"kpi-at-risk-sub\"><%= k.adapted_activities %> adapted · <%= k.recommendation_count %> recommendations</div></div>\n  <div class=\"card kpi\"><div class=\"l\">Composite risk index</div><div class=\"v\" id=\"kpi-risk-index\"><%= c.composite_risk_index.toFixed(2) %></div><div class=\"s\" id=\"kpi-risk-index-sub\">RII provisional (no survey yet)</div></div>\n</div>\n\n<% if (evm) { %>\n<!-- Real Calculated Earned Value Management (EVM) KPI Block -->\n<div class=\"card\" id=\"evm-card\" style=\"margin-top:14px;background:#fcfdfe;border:1px solid #cbd5e1\">\n  <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;border-bottom:1px solid #e2e8f0;padding-bottom:6px;flex-wrap:wrap;gap:8px\">\n    <div style=\"display:flex;align-items:center;gap:8px\">\n      <b style=\"font-size:13px;color:#1e3a8a\">📊 Earned Value Management (EVM) Calculations</b>\n      <span class=\"chip\" id=\"evm-status-chip\" style=\"font-size:10px;background:#e2e8f0;color:#334155\"><%= evm.schedule_status %> · <%= evm.cost_status %></span>\n    </div>\n    <span class=\"note\" id=\"evm-data-date-note\" style=\"font-size:11.5px\">Calculated from activity cost &amp; progress weights at data date <%= c.data_date %></span>\n  </div>\n  <div class=\"grid g4\" style=\"gap:10px\">\n    <div style=\"background:#fff;padding:8px 12px;border:1px solid var(--line);border-radius:2px\">\n      <div style=\"font-size:10.5px;color:var(--muted);text-transform:uppercase\">Planned Value (PV)</div>\n      <div style=\"font-size:19px;font-weight:600\" class=\"mono\" id=\"evm-pv\">₹<%= evm.planned_value.toLocaleString() %></div>\n      <div style=\"font-size:11px;color:var(--muted)\" id=\"evm-bac\">Budget (BAC): ₹<%= evm.budget_at_completion.toLocaleString() %></div>\n    </div>\n    <div style=\"background:#fff;padding:8px 12px;border:1px solid var(--line);border-radius:2px\">\n      <div style=\"font-size:10.5px;color:var(--muted);text-transform:uppercase\">Earned Value (EV)</div>\n      <div style=\"font-size:19px;font-weight:600;color:var(--blue)\" class=\"mono\" id=\"evm-ev\">₹<%= evm.earned_value.toLocaleString() %></div>\n      <div style=\"font-size:11px;color:var(--muted)\" id=\"evm-sv\">SV: <b class=\"<%= evm.schedule_variance >= 0 ? 'ok' : 'bad' %>\"><%= evm.schedule_variance >= 0 ? '+' : '' %>₹<%= evm.schedule_variance.toLocaleString() %></b></div>\n    </div>\n    <div style=\"background:#fff;padding:8px 12px;border:1px solid var(--line);border-radius:2px\">\n      <div style=\"font-size:10.5px;color:var(--muted);text-transform:uppercase\">Actual Cost (AC)</div>\n      <div style=\"font-size:19px;font-weight:600\" class=\"mono\" id=\"evm-ac\">₹<%= evm.actual_cost.toLocaleString() %></div>\n      <div style=\"font-size:11px;color:var(--muted)\" id=\"evm-cv\">CV: <b class=\"<%= evm.cost_variance >= 0 ? 'ok' : 'bad' %>\"><%= evm.cost_variance >= 0 ? '+' : '' %>₹<%= evm.cost_variance.toLocaleString() %></b></div>\n    </div>\n    <div style=\"background:#fff;padding:8px 12px;border:1px solid var(--line);border-radius:2px\">\n      <div style=\"font-size:10.5px;color:var(--muted);text-transform:uppercase\">Performance Indices (SPI / CPI)</div>\n      <div style=\"font-size:17px;font-weight:600;display:flex;gap:12px;align-items:baseline\">\n        <span id=\"evm-spi\" title=\"Schedule Performance Index\">SPI: <b class=\"<%= evm.spi >= 1.0 ? 'ok' : 'bad' %>\"><%= evm.spi.toFixed(2) %></b></span>\n        <span id=\"evm-cpi\" title=\"Cost Performance Index\">CPI: <b class=\"<%= evm.cpi >= 1.0 ? 'ok' : 'bad' %>\"><%= evm.cpi.toFixed(2) %></b></span>\n      </div>\n      <div style=\"font-size:11px;color:var(--muted);margin-top:2px\" id=\"evm-eac\">Estimate at finish: ₹<%= evm.estimate_at_completion.toLocaleString() %></div>\n    </div>\n  </div>\n</div>\n<% } %>\n\n<!-- REAL CALCULATED S-CURVE & SCHEDULE HORIZON -->\n<div class=\"card\" style=\"margin-top:14px\">\n  <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex-wrap:wrap;gap:8px\">\n    <div>\n      <b style=\"font-size:13px;color:#1e3a8a\">📈 Project Progress S-Curve (Planned Baseline vs Forecast Adapted)</b>\n      <div class=\"note\" style=\"font-size:11.5px\">Cumulative % progress over working-day horizon · Data date <%= c.data_date %></div>\n    </div>\n    <div style=\"display:flex;gap:14px;font-size:11.5px;align-items:center\">\n      <span style=\"color:#1d4e89\"><b>—</b> Planned (<%= c.kpis.planned_pct.toFixed(1) %>%)</span>\n      <span style=\"color:#fb8c00\"><b>---</b> Forecast</span>\n      <span style=\"color:#d50000\"><b>●</b> Actual (<%= c.kpis.actual_pct.toFixed(1) %>%)</span>\n      <a href=\"/progress<%= query ? '?' + query : '' %>\" style=\"color:var(--blue);font-weight:600\">Full Progress Breakdown →</a>\n    </div>\n  </div>\n  <div id=\"dashboard-scurve\" style=\"border:1px solid #e2e8f0;border-radius:2px;overflow:hidden\">\n    <%- generateFigureSvg('s_curve', c, gantt) %>\n  </div>\n</div>\n\n<!-- REAL CALCULATED CHARTS ROW 1 -->\n<div class=\"grid g2\" style=\"margin-top:14px\">\n  <div class=\"card\">\n    <b>Activity Status Distribution</b>\n    <div class=\"note\" style=\"font-size:11px;margin-bottom:6px\">Calculated task completion and schedule state (<%= c.project.activity_count %> activities)</div>\n    <div id=\"status-dist\" style=\"margin-top:8px\">\n      <% if (c.analytics && c.analytics.status_distribution) { %>\n        <% const st = c.analytics.status_distribution; %>\n        <% const stItems = [\n          { label: 'Completed', value: st.completed, color: '#2e7d32' },\n          { label: 'In Progress', value: st.in_progress, color: '#1976d2' },\n          { label: 'Not Started', value: st.not_started, color: '#90a4ae' },\n          { label: 'Critical Path', value: st.critical, color: '#d50000' },\n          { label: 'Near Critical', value: st.near_critical, color: '#f57c00' },\n          { label: 'Delayed Tasks', value: st.delayed, color: '#7b1fa2' }\n        ]; %>\n        <% const mxSt = Math.max(1, ...stItems.map(i => i.value)); %>\n        <% const totalSt = stItems.reduce((s, i) => s + i.value, 0); %>\n        <% stItems.forEach(function(i) { %>\n          <div style=\"display:flex;align-items:center;gap:8px;margin:6px 0\">\n            <span style=\"width:115px;font-size:11.5px;color:var(--ink);text-overflow:ellipsis;overflow:hidden;white-space:nowrap;font-weight:500\" title=\"<%= i.label %>\"><%= i.label %></span>\n            <div style=\"flex:1;background:#eee7d6;height:16px;border-radius:2px;overflow:hidden\">\n              <div style=\"height:100%;width:<%= (i.value / mxSt) * 100 %>%;background:<%= i.color %>\"></div>\n            </div>\n            <span class=\"mono\" style=\"width:40px;text-align:right;font-size:12px;font-weight:600\"><%= i.value %></span>\n            <span style=\"width:36px;font-size:11px;color:var(--muted);text-align:right\"><%= totalSt > 0 ? Math.round((i.value / totalSt) * 100) : 0 %>%</span>\n          </div>\n        <% }); %>\n      <% } %>\n    </div>\n  </div>\n  <div class=\"card\">\n    <b>Risk Distribution (activities by band of P(delay))</b>\n    <div class=\"note\" id=\"risk-bands-legend\" style=\"font-size:11px;margin-bottom:6px\"><% if (c.analytics && c.analytics.risk_bands) { %>Threshold <%= c.threshold.toFixed(2) %> · Critical (<%= c.analytics.risk_bands.critical %>), High (<%= c.analytics.risk_bands.high %>), Med (<%= c.analytics.risk_bands.medium %>), Low (<%= c.analytics.risk_bands.low %>)<% } else { %>Calculated delay probabilities from risk register<% } %></div>\n    <div id=\"risk-dist\" style=\"margin-top:8px\">\n      <% if (c.analytics && c.analytics.risk_distribution) { %>\n        <% const rd = c.analytics.risk_distribution; %>\n        <% const rb = c.analytics.risk_bands; %>\n        <% const rItems = [\n          { label: rb ? 'LOW (' + rb.low + ')' : 'LOW', value: rd.low || 0, color: '#43a047' },\n          { label: rb ? 'MEDIUM (' + rb.medium + ')' : 'MEDIUM', value: rd.medium || 0, color: '#ffb300' },\n          { label: rb ? 'HIGH (' + rb.high + ')' : 'HIGH', value: rd.high || 0, color: '#fb8c00' },\n          { label: rb ? 'CRITICAL (' + rb.critical + ')' : 'CRITICAL', value: rd.critical || 0, color: '#e53935' }\n        ]; %>\n        <% const mxR = Math.max(1, ...rItems.map(i => i.value)); %>\n        <% const totalR = rItems.reduce((s, i) => s + i.value, 0); %>\n        <% rItems.forEach(function(i) { %>\n          <div style=\"display:flex;align-items:center;gap:8px;margin:6px 0\">\n            <span style=\"width:115px;font-size:11.5px;color:var(--ink);text-overflow:ellipsis;overflow:hidden;white-space:nowrap;font-weight:500\" title=\"<%= i.label %>\"><%= i.label %></span>\n            <div style=\"flex:1;background:#eee7d6;height:16px;border-radius:2px;overflow:hidden\">\n              <div style=\"height:100%;width:<%= (i.value / mxR) * 100 %>%;background:<%= i.color %>\"></div>\n            </div>\n            <span class=\"mono\" style=\"width:40px;text-align:right;font-size:12px;font-weight:600\"><%= i.value %></span>\n            <span style=\"width:36px;font-size:11px;color:var(--muted);text-align:right\"><%= totalR > 0 ? Math.round((i.value / totalR) * 100) : 0 %>%</span>\n          </div>\n        <% }); %>\n      <% } %>\n    </div>\n  </div>\n</div>\n\n<!-- REAL CALCULATED CHARTS ROW 2 -->\n<div class=\"grid g2\" style=\"margin-top:14px\">\n  <div class=\"card\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:4px\">\n      <b>Floor-wise Construction Progress (<%= c.project.building_config ? c.project.building_config.config_label : 'Building Levels' %>)</b>\n      <a href=\"/progress<%= query ? '?' + query : '' %>\" style=\"font-size:11.5px;color:var(--blue)\">Details →</a>\n    </div>\n    <div class=\"note\" style=\"font-size:11px;margin-bottom:6px\">Calculated Planned vs Actual progress across configured floors</div>\n    <div id=\"floor-dist\" style=\"margin-top:8px;max-height:260px;overflow-y:auto;padding-right:4px\">\n      <% const flList = (c.analytics && c.analytics.floor_analytics && c.analytics.floor_analytics.length > 0) ? c.analytics.floor_analytics : (c.progress ? c.progress.floor_progress : []); %>\n      <% (flList || []).forEach(function(f) { %>\n        <div style=\"margin:7px 0;padding-bottom:5px;border-bottom:1px solid #f0ebe0\">\n          <div style=\"display:flex;justify-content:space-between;margin-bottom:2px;align-items:center\">\n            <span style=\"font-weight:600;font-size:11.5px;color:var(--ink)\"><%= f.floor %></span>\n            <span style=\"font-size:11px;color:var(--muted)\"><%= f.total_activities %> tasks <%= f.critical_activities > 0 ? '<b style=\"color:var(--critical);margin-left:4px\">(' + f.critical_activities + ' crit)</b>' : '' %></span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:40px 1fr 35px;align-items:center;gap:6px;margin:2px 0\">\n            <span style=\"font-size:10.5px;color:#1d4e89\">Plan:</span>\n            <div style=\"background:#e8edf5;height:8px;border-radius:2px;overflow:hidden\">\n              <div style=\"background:#1d4e89;height:100%;width:<%= Math.min(100, Math.max(0, f.planned_pct)) %>%\"></div>\n            </div>\n            <span class=\"mono\" style=\"font-size:10.5px;text-align:right\"><%= f.planned_pct.toFixed(0) %>%</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:40px 1fr 35px;align-items:center;gap:6px;margin:2px 0\">\n            <span style=\"font-size:10.5px;color:<%= f.actual_pct < f.planned_pct ? '#e53935' : '#43a047' %>\">Act:</span>\n            <div style=\"background:#e8edf5;height:8px;border-radius:2px;overflow:hidden\">\n              <div style=\"background:<%= f.actual_pct < f.planned_pct ? '#e53935' : '#43a047' %>;height:100%;width:<%= Math.min(100, Math.max(0, f.actual_pct)) %>%\"></div>\n            </div>\n            <span class=\"mono\" style=\"font-size:10.5px;text-align:right\"><%= f.actual_pct.toFixed(0) %>%</span>\n          </div>\n        </div>\n      <% }); %>\n    </div>\n  </div>\n  <div class=\"card\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:4px\">\n      <b>Forecast Completion Trend by Cycle</b>\n      <span class=\"note\" style=\"font-size:11px\"><%= (c.forecast_trend || []).length %> points</span>\n    </div>\n    <div class=\"note\" style=\"font-size:11px;margin-bottom:6px\">History of schedule recalculations and adaptations</div>\n    <div id=\"forecast-trend-chart\" style=\"margin-bottom:10px;border:1px solid #e2e8f0;border-radius:2px;overflow:hidden\">\n      <%- generateFigureSvg('forecast_trend', c, gantt) %>\n    </div>\n    <table style=\"margin-top:8px\">\n      <thead>\n        <tr><th>Cycle</th><th>Data Date</th><th class=\"num\">Forecast Finish</th></tr>\n      </thead>\n      <tbody id=\"forecast-trend-tbody\">\n        <% (c.forecast_trend || []).forEach(function(p) { %>\n        <tr><td><b><%= p.label %></b></td><td><%= p.data_date || '–' %></td><td class=\"num mono\"><b><%= p.completion_date %></b></td></tr>\n        <% }); %>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n<div style=\"display:flex;justify-content:space-between;align-items:center;margin:22px 0 8px;border-bottom:1px solid var(--line);padding-bottom:4px\">\n  <h2 style=\"margin:0;border:none;padding:0\">Highest-risk activities</h2>\n  <a href=\"/builder<%= query ? '?' + query : '' %>\" class=\"btn alt\" style=\"font-size:11.5px;padding:3px 8px\">＋ Add Task / Open Schedule Builder →</a>\n</div>\n<% if (c.model) { %>\n<div class=\"scroll\" style=\"max-height:none\"><table id=\"highest-risk-table\"><thead><tr><th>ID</th><th>Activity</th><th>P(delay)</th><th>Risk</th><th>Pred. delay (d)</th><th>Injected (d)</th><th>Critical</th><th>Main drivers</th></tr></thead>\n<tbody id=\"highest-risk-tbody\">\n<% const sortedActs = c.activities.slice().sort((a,b) => (b.p_delay || 0) - (a.p_delay || 0)).slice(0, 8); %>\n<% sortedActs.forEach(function(a) { %><tr><td><%= a.activity_id %></td><td><%= a.name %></td><td class=\"num\"><%= a.p_delay !== null ? a.p_delay.toFixed(2) : '-' %></td><td><span class=\"chip <%= a.risk_band %>\"><%= a.risk_band %></span></td><td class=\"num\"><%= a.predicted_delay_days %></td><td class=\"num\"><%= a.injected_days %></td><td><% if (a.critical) { %><span class=\"tag\">critical</span><% } %></td><td><%= a.drivers %></td></tr><% }); %>\n</tbody></table></div>\n<% } else { %>\n<p class=\"note\">No ML model available. Run <code>adaptive-scheduler train</code>.</p>\n<% } %>\n<%- include('partials/footer') %>\n",
  "error": "<%- include('partials/header') %>\n<div class=\"warn\"><b>Request could not be processed.</b><br><%= message %></div>\n<%- include('partials/footer') %>\n",
  "factors": "<%- include('partials/header') %>\n<h2>Delay factors and live risk register</h2>\n<div class=\"warn\" style=\"background:#fff3e0;border-color:#e85d04\">RII values are <b>PROVISIONAL</b> – the questionnaire survey has not been conducted; they are not survey-validated real-world values.</div>\n<p>Composite risk index (RII-weighted, normalised 0–4 scores): <b class=\"mono\"><%= c.composite_risk_index.toFixed(3) %></b> · Dominant: <% c.dominant_factors.forEach(function(f, idx) { %><%= f[1] %> (score <%= f[2] %>)<%= idx < c.dominant_factors.length - 1 ? ', ' : '' %><% }); %></p>\n<table><tr><th>ID</th><th>Factor</th><th>RII (provisional)</th><th>Score 0–4</th><th></th><th>Note</th></tr>\n<% (c.factors || []).forEach(function(f) { %>\n<tr>\n  <td><%= f.factor_id %></td>\n  <td><%= f.factor %></td>\n  <td class=\"num\"><%= f.rii.toFixed(2) %></td>\n  <td class=\"num\"><%= f.score %></td>\n  <td style=\"width:160px\"><div class=\"bar\"><i style=\"width:<%= f.score * 25 %>%\"></i></div></td>\n  <td><%= f.note %></td>\n</tr>\n<% }); %>\n</table>\n<%- include('partials/footer') %>\n",
  "gantt": "<%- include('partials/header') %>\n<div class=\"controls\">\n  <label>Zoom <input id=\"zoom\" type=\"range\" min=\"1.5\" max=\"14\" step=\"0.5\" value=\"4\"></label>\n  <label>Filter <select id=\"filter\">\n    <option value=\"all\">All activities</option>\n    <option value=\"critical\">Critical path</option>\n    <option value=\"near\">Near-critical</option>\n    <option value=\"atrisk\">High / critical risk</option>\n    <option value=\"delayed\">Adapted (delay injected)</option>\n  </select></label>\n  <label>Floor <select id=\"floor-select\">\n    <option value=\"all\">All floors</option>\n    <% if (c.project && c.project.floors) { %>\n      <% c.project.floors.forEach(function(fl) { %>\n        <option value=\"<%= fl %>\"><%= fl %></option>\n      <% }); %>\n    <% } %>\n  </select></label>\n  <label>Search <input id=\"find\" placeholder=\"name or id\"></label>\n  <label><input id=\"base\" type=\"checkbox\" checked> Baseline</label>\n  <span id=\"count\" class=\"note\"></span>\n  <a href=\"/builder<%= query ? '?' + query : '' %>\" class=\"btn alt\" style=\"margin-left:auto;font-size:12px;padding:4px 10px\">＋ Input / Edit Tasks</a>\n</div>\n<div class=\"legend\">\n  <span><i style=\"background:#cfd8dc\"></i>Baseline</span>\n  <span><i style=\"background:#43a047\"></i>Low</span>\n  <span><i style=\"background:#ffb300\"></i>Medium</span>\n  <span><i style=\"background:#fb8c00\"></i>High</span>\n  <span><i style=\"background:#e53935\"></i>Critical risk</span>\n  <span><i style=\"border:2px solid #d50000\"></i>Critical path (red outline)</span>\n  <span>Dashed blue line = data date. Axis = working-day offsets.</span>\n</div>\n<div id=\"gantt\" class=\"gantt-wrap\"></div>\n<script id=\"gantt-initial-data\" type=\"application/json\"><%- JSON.stringify(gantt) %></script>\n<%- include('partials/footer') %>\n",
  "predictions": "<%- include('partials/header') %>\n<h2>Delay predictions</h2>\n<p class=\"note\">Model trained on SYNTHETIC data<% if (c.model) { %>: <%= c.model.classifier %> (probability) + <%= c.model.regressor %> (delay days); tuned at-risk threshold <%= c.model.at_risk_threshold %><% } %>. <a href=\"/export/predictions.csv?<%= query %>\">Export CSV</a></p>\n<% if (c.model) { %>\n<div class=\"scroll\"><table><tr><th>ID</th><th>Activity</th><th>Type</th><th>P(delay)</th><th>Risk</th><th>Predicted delay (d)</th><th>Injected (d)</th><th>SHAP drivers (factor share of positive SHAP)</th></tr>\n<% const sortedActs = c.activities.slice().sort((a,b) => (b.p_delay || 0) - (a.p_delay || 0)); %>\n<% sortedActs.forEach(function(a) { %>\n<tr>\n  <td><%= a.activity_id %></td>\n  <td><%= a.name %> <% if (a.critical) { %><span class=\"tag\">critical</span><% } %></td>\n  <td><%= a.type %></td>\n  <td class=\"num\"><%= a.p_delay !== null ? a.p_delay.toFixed(3) : '-' %></td>\n  <td><span class=\"chip <%= a.risk_band %>\"><%= a.risk_band %></span></td>\n  <td class=\"num\"><%= a.predicted_delay_days %></td>\n  <td class=\"num\"><%= a.injected_days %><%= a.injected_source === 'observed' ? ' (obs.)' : '' %></td>\n  <td>\n    <%= a.drivers %>\n    <% if (c.explanations && c.explanations[a.activity_id]) { %>\n    <details>\n      <summary>top SHAP features</summary>\n      <% (c.explanations[a.activity_id].top_features || []).forEach(function(t) { %>\n      <div class=\"note\"><%= t.feature %> = <%= t.value.toFixed(2) %> → <%= (t.shap >= 0 ? '+' : '') + t.shap.toFixed(3) %></div>\n      <% }); %>\n    </details>\n    <% } %>\n  </td>\n</tr>\n<% }); %>\n</table></div>\n<% } else { %>\n<p>No ML model available. Run <code>adaptive-scheduler train</code>.</p>\n<% } %>\n<%- include('partials/footer') %>\n",
  "progress": "<%- include('partials/header') %>\n<% const p = c.progress; %>\n<% const evm = c.analytics ? c.analytics.evm : null; %>\n<div class=\"grid g4\">\n  <div class=\"card kpi\"><div class=\"l\">Planned Progress</div><div class=\"v\"><%= p.planned_pct.toFixed(1) %> %</div><div class=\"s\"><%= p.weighting %>-weighted duration</div></div>\n  <div class=\"card kpi\"><div class=\"l\">Actual Progress</div><div class=\"v\"><%= p.actual_pct.toFixed(1) %> %</div><div class=\"s\">data date <%= p.data_date %></div></div>\n  <div class=\"card kpi\"><div class=\"l\">Progress Variance</div><div class=\"v <%= p.variance_pct < 0 ? 'bad' : 'ok' %>\"><%= (p.variance_pct >= 0 ? '+' : '') + p.variance_pct.toFixed(1) %> pts</div><div class=\"s\">performance index <%= p.performance_index !== null ? p.performance_index : '–' %></div></div>\n  <div class=\"card kpi\"><div class=\"l\">Working Days Elapsed</div><div class=\"v\"><%= p.elapsed_working_days %></div><div class=\"s\">of baseline schedule</div></div>\n</div>\n\n<% if (evm) { %>\n<!-- Earned Value Management (EVM) Metrics Row -->\n<div class=\"grid g4\" style=\"margin-top:10px\">\n  <div class=\"card kpi\">\n    <div class=\"l\">Planned Value (PV)</div>\n    <div class=\"v\" style=\"font-size:20px\">₹<%= evm.planned_value.toLocaleString() %></div>\n    <div class=\"s\">Budget (BAC): ₹<%= evm.budget_at_completion.toLocaleString() %></div>\n  </div>\n  <div class=\"card kpi\">\n    <div class=\"l\">Earned Value (EV)</div>\n    <div class=\"v\" style=\"font-size:20px;color:var(--blue)\">₹<%= evm.earned_value.toLocaleString() %></div>\n    <div class=\"s\">SV: <b class=\"<%= evm.schedule_variance >= 0 ? 'ok' : 'bad' %>\"><%= evm.schedule_variance >= 0 ? '+' : '' %>₹<%= evm.schedule_variance.toLocaleString() %></b></div>\n  </div>\n  <div class=\"card kpi\">\n    <div class=\"l\">Actual Cost (AC)</div>\n    <div class=\"v\" style=\"font-size:20px\">₹<%= evm.actual_cost.toLocaleString() %></div>\n    <div class=\"s\">CV: <b class=\"<%= evm.cost_variance >= 0 ? 'ok' : 'bad' %>\"><%= evm.cost_variance >= 0 ? '+' : '' %>₹<%= evm.cost_variance.toLocaleString() %></b></div>\n  </div>\n  <div class=\"card kpi\">\n    <div class=\"l\">SPI / CPI</div>\n    <div class=\"v\" style=\"font-size:20px\"><%= evm.spi.toFixed(2) %> / <%= evm.cpi.toFixed(2) %></div>\n    <div class=\"s\"><%= evm.schedule_status %> · <%= evm.cost_status %></div>\n  </div>\n</div>\n<% } %>\n\n<h2>S-curve (Planned Baseline vs Forecast Adapted)</h2>\n<div class=\"card\">\n  <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex-wrap:wrap;gap:8px\">\n    <div style=\"font-size:12px;color:var(--muted)\">Cumulative percentage of project progress over the working-day schedule horizon.</div>\n    <div style=\"display:flex;gap:14px;font-size:12px\">\n      <span style=\"color:#1d4e89\"><b>—</b> Planned (baseline)</span>\n      <span style=\"color:#fb8c00\"><b>---</b> Forecast (adapted)</span>\n      <span style=\"color:#d50000\"><b>●</b> Actual (<%= p.actual_pct.toFixed(1) %>%)</span>\n    </div>\n  </div>\n  <div id=\"scurve\" style=\"border:1px solid #e2e8f0;border-radius:2px;overflow:hidden\">\n    <%- generateFigureSvg('s_curve', c, gantt) %>\n  </div>\n</div>\n\n<% if (p.floor_progress && p.floor_progress.length > 0) { %>\n<h2>Floor-wise Progress Breakdown (<%= c.project && c.project.building_config && c.project.building_config.config_label ? c.project.building_config.config_label : 'Building Levels' %>)</h2>\n<div class=\"scroll\">\n  <table>\n    <thead>\n      <tr>\n        <th>Level / Floor</th>\n        <th class=\"num\">Total Tasks</th>\n        <th class=\"num\">Completed</th>\n        <th class=\"num\">In Progress</th>\n        <th class=\"num\">Critical</th>\n        <th class=\"num\">Planned %</th>\n        <th class=\"num\">Actual %</th>\n        <th class=\"num\">Variance</th>\n      </tr>\n    </thead>\n    <tbody>\n      <% p.floor_progress.forEach(function(f) { %>\n      <tr>\n        <td><b class=\"chip\" style=\"font-size:11px\"><%= f.floor %></b></td>\n        <td class=\"num\"><%= f.total_activities %></td>\n        <td class=\"num\"><%= f.completed_activities %></td>\n        <td class=\"num\"><%= f.in_progress_activities %></td>\n        <td class=\"num <%= f.critical_activities > 0 ? 'bad' : '' %>\"><%= f.critical_activities %></td>\n        <td class=\"num\"><%= f.planned_pct.toFixed(1) %> %</td>\n        <td class=\"num\"><%= f.actual_pct.toFixed(1) %> %</td>\n        <td class=\"num <%= f.variance_pct < 0 ? 'bad' : 'ok' %>\"><%= (f.variance_pct >= 0 ? '+' : '') + f.variance_pct.toFixed(1) %> pts</td>\n      </tr>\n      <% }); %>\n    </tbody>\n  </table>\n</div>\n<% } %>\n\n<h2>Activities in progress or behind plan</h2>\n<div class=\"scroll\">\n  <table>\n    <thead>\n      <tr>\n        <th>ID</th>\n        <th>Activity</th>\n        <th class=\"num\">Planned %</th>\n        <th class=\"num\">Actual %</th>\n        <th class=\"num\">Variance</th>\n      </tr>\n    </thead>\n    <tbody>\n      <% const filteredActs = (p.activities || []).filter(a => a.planned_pct > 0 || a.actual_pct > 0).sort((a,b) => a.variance_pct - b.variance_pct); %>\n      <% if (filteredActs.length > 0) { %>\n        <% filteredActs.forEach(function(a) { %>\n        <tr>\n          <td class=\"mono\"><b><%= a.activity_id %></b></td>\n          <td><%= a.name %></td>\n          <td class=\"num\"><%= a.planned_pct %> %</td>\n          <td class=\"num\"><%= a.actual_pct %> %</td>\n          <td class=\"num <%= a.variance_pct < 0 ? 'bad' : 'ok' %>\"><%= (a.variance_pct >= 0 ? '+' : '') + a.variance_pct.toFixed(1) %> pts</td>\n        </tr>\n        <% }); %>\n      <% } else { %>\n        <tr><td colspan=\"5\" style=\"text-align:center;color:var(--muted);padding:14px\">All activities on schedule or not yet started</td></tr>\n      <% } %>\n    </tbody>\n  </table>\n</div>\n<p class=\"note\"><a href=\"/export/progress.csv?<%= query %>\">Export CSV</a></p>\n<%- include('partials/footer') %>\n",
  "recommendations": "<%- include('partials/header') %>\n<h2>Ranked mitigation recommendations</h2>\n<p class=\"note\">Only critical and near-critical activities. \"Engineering-judgement\" estimates are provisional percentages; crash estimates follow crash limits and cost slopes. <a href=\"/export/recommendations.csv?<%= query %>\">Export CSV</a></p>\n<% if (c.recommendations && c.recommendations.length > 0) { %>\n<div class=\"scroll\"><table><tr><th>#</th><th>Activity</th><th>Status</th><th>Cause</th><th>SHAP share</th><th>Recommended action</th><th>Recovery (d)</th><th>Cost (INR)</th><th>Basis</th><th>Priority</th></tr>\n<% c.recommendations.forEach(function(r) { %>\n<tr>\n  <td class=\"num\"><%= r.rank %></td>\n  <td><%= r.activity_id %> <%= r.activity_name %></td>\n  <td><%= r.status %></td>\n  <td><%= r.cause %></td>\n  <td class=\"num\"><%= r.shap_share !== null ? Math.round(r.shap_share * 100) + '%' : '–' %></td>\n  <td><%= r.action %></td>\n  <td class=\"num\"><%= r.recovery_days %></td>\n  <td class=\"num\"><%= Math.round(r.cost_impact_inr).toLocaleString() %></td>\n  <td><%= r.basis %></td>\n  <td><%= r.priority %></td>\n</tr>\n<% }); %>\n</table></div>\n<% } else { %>\n<p>No recommendations: no critical or near-critical activity currently carries an injected delay (or no model is available).</p>\n<% } %>\n<%- include('partials/footer') %>\n",
  "reports": "<%- include('partials/header') %>\n<h2>Reports and exports</h2>\n<div class=\"controls\">\n  <form method=\"post\" action=\"/reports/generate?<%= query %>\"><button>Generate PDF report</button></form>\n  <a class=\"btn alt\" href=\"/reports/download\">Download PDF</a>\n  <a class=\"btn alt\" href=\"/export/activities.csv?<%= query %>\">Activities CSV</a>\n  <a class=\"btn alt\" href=\"/export/recommendations.csv?<%= query %>\">Recommendations CSV</a>\n  <a class=\"btn alt\" href=\"/export/predictions.csv?<%= query %>\">Predictions CSV</a>\n  <a class=\"btn alt\" href=\"/export/resources.csv?<%= query %>\">Resources CSV</a>\n</div>\n<% if (generated) { %><div class=\"banner\">Report generated: <%= generated %></div><% } %>\n\n<h2>JSON API</h2>\n<ul>\n  <li><a href=\"/api/cycle?<%= query %>\">GET /api/cycle</a> – full cycle result (CPM, EVM, risk classifications)</li>\n  <li><a href=\"/api/gantt?<%= query %>\">GET /api/gantt</a> – working-day offsets, critical path, activity float</li>\n  <li><a href=\"/api/activities?<%= query %>\">GET /api/activities</a> – task list with P(delay) and adapted durations</li>\n  <li><a href=\"/api/recommendations?<%= query %>\">GET /api/recommendations</a> – prioritized mitigation actions</li>\n  <li><a href=\"/api/analytics?<%= query %>\">GET /api/analytics</a> – EVM metrics, floor analytics, and risk bands</li>\n</ul>\n\n<div style=\"display:flex;justify-content:space-between;align-items:center;margin:24px 0 10px;border-bottom:1px solid var(--line);padding-bottom:6px;flex-wrap:wrap;gap:8px\">\n  <h2 style=\"margin:0;border:none;padding:0\">Project Analytics &amp; Calculated Charts</h2>\n  <span class=\"note\">Generated dynamically from live scheduling engine (data date: <%= c.data_date %>, threshold: <%= c.threshold.toFixed(2) %>)</span>\n</div>\n\n<% \nconst FIG_META = {\n  gantt_chart: { title: 'Project Master Schedule Gantt', desc: 'Baseline timeline (gray) vs current forecast with critical path outlined in red.' },\n  s_curve: { title: 'Cumulative Progress S-Curve', desc: 'Planned baseline curve vs adapted forecast with actual progress marker.' },\n  risk_distribution: { title: 'Activity Risk Distribution', desc: 'Activity counts partitioned across Low, Medium, High, and Critical risk bands.' },\n  forecast_trend: { title: 'Forecast Completion Trend by Cycle', desc: 'Project completion date progression across scheduling revisions.' },\n  resource_histogram: { title: 'Daily Resource Demand Histograms', desc: 'Manpower / equipment demand profiles vs capacity limits (red = over-allocated).' },\n  shap_global_importance: { title: 'Delay Factor Severity & Impact', desc: 'Ranking of site risk drivers by provisional RII and severity impact scores.' }\n};\n%>\n\n<div class=\"grid g2\">\n  <% ['s_curve', 'gantt_chart', 'risk_distribution', 'forecast_trend', 'resource_histogram', 'shap_global_importance'].forEach(function(n) { %>\n  <% const meta = FIG_META[n] || { title: n, desc: '' }; %>\n  <div class=\"card\" style=\"display:flex;flex-direction:column;justify-content:space-between\">\n    <div>\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:4px\">\n        <b><%= meta.title %></b>\n        <a class=\"btn alt\" style=\"font-size:11px;padding:2px 8px\" href=\"/figures/<%= n %>.svg<%= query ? '?' + query : '' %>\" target=\"_blank\" download=\"<%= n %>.svg\">Download SVG</a>\n      </div>\n      <div class=\"note\" style=\"font-size:11.5px;margin-bottom:8px\"><%= meta.desc %></div>\n    </div>\n    <div style=\"border:1px solid var(--line);border-radius:2px;overflow:hidden;background:#fff\">\n      <img class=\"fig\" src=\"/figures/<%= n %>.svg<%= query ? '?' + query : '' %>\" alt=\"<%= meta.title %>\" style=\"width:100%;height:auto;display:block;border:none\">\n    </div>\n  </div>\n  <% }); %>\n</div>\n<%- include('partials/footer') %>\n",
  "resources": "<%- include('partials/header') %>\n<h2>Resource utilisation (current schedule)</h2>\n<p class=\"note\">Demand in resource-days against availability declared in project.json. <a href=\"/export/resources.csv?<%= query %>\">Export CSV</a></p>\n<div class=\"scroll\" style=\"max-height:none\"><table><tr><th>Resource</th><th>Available</th><th>Peak demand</th><th>Resource-days</th><th>Mean active util. %</th><th>Util. % of project</th><th>Over-alloc. days</th><th>Shortage (res-days)</th></tr>\n<% (c.resources.summary || []).forEach(function(r) { %>\n<tr>\n  <td><%= r.resource %> – <%= r.name %></td>\n  <td class=\"num\"><%= r.available %></td>\n  <td class=\"num <%= r.peak_demand > r.available ? 'bad' : '' %>\"><%= Math.round(r.peak_demand) %></td>\n  <td class=\"num\"><%= Math.round(r.resource_days) %></td>\n  <td class=\"num\"><%= r.mean_active_utilisation_pct %></td>\n  <td class=\"num\"><%= r.utilisation_pct %></td>\n  <td class=\"num\"><%= r.over_allocated_days %></td>\n  <td class=\"num\"><%= Math.round(r.shortage_resource_days) %></td>\n</tr>\n<% }); %>\n</table></div>\n<h2>Over-allocation windows</h2>\n<% if (c.resources.over_allocation_windows && c.resources.over_allocation_windows.length > 0) { %>\n<table><tr><th>Resource</th><th>From</th><th>To</th><th>Working days</th><th>Available</th><th>Peak demand</th><th>Peak shortage</th><th>Shortage (res-days)</th></tr>\n<% c.resources.over_allocation_windows.forEach(function(w) { %>\n<tr>\n  <td><%= w.resource %></td>\n  <td class=\"num\"><%= w.start_date %></td>\n  <td class=\"num\"><%= w.end_date %></td>\n  <td class=\"num\"><%= w.working_days %></td>\n  <td class=\"num\"><%= w.available %></td>\n  <td class=\"num\"><%= Math.round(w.peak_demand) %></td>\n  <td class=\"num\"><%= Math.round(w.peak_shortage) %></td>\n  <td class=\"num\"><%= Math.round(w.shortage_resource_days) %></td>\n</tr>\n<% }); %>\n</table>\n<% } else { %>\n<p>No over-allocation.</p>\n<% } %>\n<h2>Daily demand vs availability (red = over-allocated)</h2>\n<div id=\"demand\" style=\"border:1px solid #e2e8f0;border-radius:2px;overflow:hidden;background:#fff;margin-top:8px\">\n  <%- generateFigureSvg('resource_histogram', c, gantt) %>\n</div>\n<%- include('partials/footer') %>\n",
  "partials/header": "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title><%= c && c.project ? c.project.name : 'Adaptive Scheduler' %></title>\n  <meta name=\"description\" content=\"AI-based self-adaptive construction scheduling system with CPM network analysis, delay prediction, and risk mitigation.\">\n  <link rel=\"stylesheet\" href=\"/static/style.css\">\n</head>\n<body data-page=\"<%= active %>\">\n<header class=\"titleblock\">\n  <div class=\"id\">\n    <h1>AI-Based Self-Adaptive Construction Scheduling</h1>\n    <div class=\"sub\"><% if (c && c.project) { %><%= c.project.name %> · <%= c.project.building_config && c.project.building_config.config_label ? '[' + c.project.building_config.config_label + '] · ' : '' %><%= c.project.activity_count %> activities · <%= c.project.dependency_count %> links · start <%= c.project.start_date %> · <span id=\"header-data-date-badge\">status date <%= c.data_date %></span><% } %></div>\n  </div>\n  <% if (c) { %>\n  <form class=\"params\" id=\"params-form\" method=\"get\">\n    <label>Data date<input type=\"date\" id=\"data-date-input\" name=\"data_date\" value=\"<%= c.data_date %>\"></label>\n    <label>Mode<select id=\"mode-select\" name=\"mode\"><option value=\"expected\" <%= c.mode === 'expected' ? 'selected' : '' %>>expected value</option><option value=\"conservative\" <%= c.mode === 'conservative' ? 'selected' : '' %>>conservative</option></select></label>\n    <label>Threshold<input type=\"number\" step=\"0.05\" min=\"0\" max=\"1\" id=\"threshold-input\" name=\"threshold\" value=\"<%= c.threshold %>\" style=\"width:70px\"></label>\n    <button type=\"submit\" id=\"btn-apply-threshold\">Apply</button>\n    <button class=\"alt\" formmethod=\"post\" formaction=\"/run?<%= query %>\" title=\"Run one cycle and save it as a new version\">Run &amp; store cycle</button>\n  </form>\n  <% } %>\n</header>\n<div id=\"threshold-feedback\" style=\"display:none;padding:8px 24px;font-size:12px;font-weight:500;transition:all .2s ease\"></div>\n<nav>\n  <% pages.forEach(function([ep, label, path]) { %>\n    <a href=\"<%= path %><%= query ? '?' + query : '' %>\" class=\"<%= active === ep ? 'on' : '' %>\"><%= label %></a>\n  <% }); %>\n</nav>\n<main>\n  <% if (c) { %>\n    <div class=\"banner\"><b>Synthetic demonstration data.</b> <%= c.notice %></div>\n    <% (c.warnings || []).forEach(function(w) { %>\n      <div class=\"warn\">⚠ <%= w %></div>\n    <% }); %>\n    <script id=\"cycle-data\" type=\"application/json\"><%- JSON.stringify(c) %></script>\n  <% } %>\n",
  "partials/footer": "</main>\n<div id=\"tip\"></div>\n<script src=\"/static/app.js\"></script>\n</body>\n</html>\n"
};
